import type { BankQuestion } from "@/lib/bank";

/** Units, Dimensions and Errors (Physics (JEE/NEET)): 138 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"phy-units-measurement-1","question":"The dimensional formula of Planck's constant h is:","options":["[MLT⁻¹]","[ML²T⁻³]","[ML²T⁻¹]","[ML²T⁻²]"],"answer":2,"explanation":"From E = hν, h = E/ν = [ML²T⁻²]/[T⁻¹] = [ML²T⁻¹], the same as angular momentum. [ML²T⁻²] is energy itself, not energy divided by frequency.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"phy-units-measurement-2","question":"Which of the following pairs of quantities have the same dimensions?","options":["Work and torque","Momentum and energy","Power and pressure","Force and impulse"],"answer":0,"explanation":"Work = force × displacement and torque = force × perpendicular distance; both are [ML²T⁻²]. Impulse is force × time, so it has the dimensions of momentum, not force.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-units-measurement-3","question":"The number of significant figures in 0.007020 is:","options":["4","6","3","7"],"answer":0,"explanation":"Leading zeros only fix the decimal point and are not significant; the digits 7, 0, 2 and the trailing 0 after the decimal point are, giving 4.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"phy-units-measurement-4","question":"The dimensional formula of the universal gravitational constant G is:","options":["[M⁻²L³T⁻²]","[ML³T⁻²]","[M⁻¹L²T⁻²]","[M⁻¹L³T⁻²]"],"answer":3,"explanation":"From F = Gm₁m₂/r², G = Fr²/m² = [MLT⁻²][L²]/[M²] = [M⁻¹L³T⁻²].","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-units-measurement-5","question":"In a vernier callipers, 20 divisions of the vernier scale coincide with 19 divisions of the main scale, and one main-scale division is 0.5 mm. The least count is:","options":["0.5 mm","0.025 mm","0.0025 mm","0.05 mm"],"answer":1,"explanation":"1 VSD = (19/20) MSD, so LC = 1 MSD − 1 VSD = (1/20) MSD = 0.5/20 = 0.025 mm. Taking 1/20 of 1 mm instead of 0.5 mm gives 0.05 mm.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-6","question":"A screw gauge has a pitch of 0.5 mm and 50 divisions on its circular scale, and no zero error. While measuring a wire, the main-scale reading is 3 mm and the 35th circular division coincides with the reference line. The diameter of the wire is:","options":["6.50 mm","3.35 mm","3.70 mm","3.035 mm"],"answer":1,"explanation":"LC = 0.5/50 = 0.01 mm; reading = 3 + 35 × 0.01 = 3.35 mm. Using LC = 0.02 mm (1/50 of 1 mm) wrongly gives 3.70 mm.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-units-measurement-7","question":"The momentum of a body of exactly known mass is measured with a maximum error of 2%. The maximum percentage error in its kinetic energy calculated from this measurement is:","options":["8%","1%","2%","4%"],"answer":3,"explanation":"K = p²/2m, so ΔK/K = 2(Δp/p) = 2 × 2% = 4%; the error in a power multiplies by that power.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-units-measurement-8","question":"The dimensional formula of the permittivity of free space ε₀ is:","options":["[M⁻¹L⁻²T⁴A²]","[ML³T⁻⁴A⁻²]","[M⁻¹L⁻³T⁴A²]","[M⁻¹L⁻³T²A²]"],"answer":2,"explanation":"From Coulomb's law ε₀ = q²/(4πFr²) = [A²T²]/([MLT⁻²][L²]) = [M⁻¹L⁻³T⁴A²]. [ML³T⁻⁴A⁻²] is its reciprocal (the dimensions of 1/ε₀).","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-9","question":"The lengths 2.5 m, 0.125 m and 1.04 m are added. The sum, written to the correct number of significant figures, is:","options":["3.665 m","3.67 m","3.66 m","3.7 m"],"answer":3,"explanation":"In addition the result keeps as many decimal places as the least precise term; 2.5 has one decimal place, so 3.665 m is rounded to 3.7 m.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-units-measurement-10","question":"In the van der Waals equation (P + a/V²)(V − b) = RT, the dimensions of a/b are:","options":["[L³]","[ML²T⁻²]","[ML⁵T⁻²]","[ML⁻¹T⁻²]"],"answer":1,"explanation":"Only like quantities can be added, so a/V² has the dimensions of pressure (a = PV²) and b those of volume. Then a/b = PV, which is energy, [ML²T⁻²]. [ML⁵T⁻²] is a alone.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-11","question":"The length and breadth of a rectangle are measured as (5.0 ± 0.1) cm and (2.0 ± 0.1) cm. Its area with the maximum error is:","options":["(10.0 ± 0.1) cm²","(10.0 ± 0.2) cm²","(10.0 ± 0.7) cm²","(10.0 ± 0.5) cm²"],"answer":2,"explanation":"Relative error = 0.1/5.0 + 0.1/2.0 = 0.02 + 0.05 = 0.07, so ΔA = 0.07 × 10.0 = 0.7 cm². Adding the absolute errors (0.2) is the rule for sums, not products.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-units-measurement-12","question":"If velocity V, time T and force F are chosen as the fundamental quantities, the dimensional formula of mass is:","options":["[F V T⁻¹]","[F V⁻¹ T]","[F² V⁻¹ T]","[F V⁻¹ T⁻¹]"],"answer":1,"explanation":"F = ma = M·V/T, so M = F·T/V = [F V⁻¹ T]. A quick check: F·T is impulse, i.e. momentum, and momentum divided by velocity is mass.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-13","question":"A vernier callipers with least count 0.1 mm has a zero error of −0.3 mm. While measuring a rod, the main-scale reading is 24 mm and the 6th vernier division coincides. The corrected length of the rod is:","options":["24.3 mm","24.6 mm","25.2 mm","24.9 mm"],"answer":3,"explanation":"Observed reading = 24 + 6 × 0.1 = 24.6 mm. Corrected = observed − zero error = 24.6 − (−0.3) = 24.9 mm; subtracting 0.3 instead gives the trap 24.3 mm.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-14","question":"Which of the following combinations does NOT have the dimensions of time? (R = resistance, L = inductance, C = capacitance)","options":["RC","R/L","L/R","√(LC)"],"answer":1,"explanation":"RC and L/R are the time constants of RC and LR circuits, and √(LC) = 1/ω for an LC circuit, so all three are times. R/L is the reciprocal of a time constant, with dimensions [T⁻¹].","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-units-measurement-15","question":"The radius of a sphere measured with a vernier callipers of least count 0.01 cm is 2.50 cm. The maximum percentage error in its calculated volume is:","options":["0.8%","3.6%","1.2%","0.4%"],"answer":2,"explanation":"Δr/r = 0.01/2.50 = 0.4%, and V ∝ r³, so ΔV/V = 3 × 0.4% = 1.2%. 0.4% is the error in r alone.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-units-measurement-16","question":"The value of G is 6.67 × 10⁻¹¹ N m² kg⁻² in SI units. Its value in CGS units (dyn cm² g⁻²) is:","options":["6.67 × 10⁻¹⁴","6.67 × 10⁻⁸","6.67 × 10⁻⁵","6.67 × 10⁻⁹"],"answer":1,"explanation":"G has dimensions [M⁻¹L³T⁻²]: (1 kg)⁻¹ = (10³ g)⁻¹ and (1 m)³ = 10⁶ cm³, so the factor is 10⁻³ × 10⁶ = 10³, giving 6.67 × 10⁻⁸ in CGS.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-17","question":"The time period of a pendulum is measured five times as 1.52 s, 1.48 s, 1.55 s, 1.45 s and 1.50 s. The percentage error in the measurement (mean absolute error relative to the mean) is about:","options":["2.8%","1.9%","0.9%","3.3%"],"answer":1,"explanation":"Mean = 7.50/5 = 1.50 s. Absolute deviations: 0.02, 0.02, 0.05, 0.05, 0 → mean absolute error = 0.14/5 = 0.028 s. Percentage error = 0.028/1.50 × 100 ≈ 1.9%.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-units-measurement-18","question":"A quantity X = a²b³/(c√d). The percentage errors in a, b, c and d are 1%, 2%, 3% and 4% respectively. The maximum percentage error in X is:","options":["13%","16%","10%","15%"],"answer":0,"explanation":"ΔX/X = 2(1%) + 3(2%) + 1(3%) + ½(4%) = 2 + 6 + 3 + 2 = 13%. Using the full 4% for √d instead of half of it gives 15%; ignoring the powers altogether gives 10%.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-units-measurement-19","question":"The frequency of vibration of a stretched string depends on its length l, tension T and mass per unit length μ. Using dimensional analysis, if the length is halved and the tension is made four times, the frequency becomes:","options":["8 times","2 times","4 times","unchanged"],"answer":2,"explanation":"Dimensional analysis gives f = k·(1/l)√(T/μ). Halving l doubles f and quadrupling T doubles it again (√4 = 2), so f becomes 2 × 2 = 4 times.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-20","question":"In a new system of units the unit of mass is 10 kg, the unit of length is 1 km and the unit of time is 1 minute. One joule expressed in this system is about:","options":["3.6 × 10⁻⁴ units","3.6 × 10⁻² units","6 × 10⁻³ units","2.8 × 10³ units"],"answer":0,"explanation":"New energy unit = 10 kg × (10³ m)² / (60 s)² = 10⁷/3600 J ≈ 2778 J. Hence 1 J = 1/2778 ≈ 3.6 × 10⁻⁴ new units; 2.8 × 10³ is the size of the new unit, not the conversion of 1 J.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-21","question":"How many of the following statements are correct?\n(A) The number 6.0200 has five significant figures.\n(B) Changing the unit of a measured quantity changes the number of its significant figures.\n(C) The maximum relative error in a product of two quantities is the sum of their relative errors.\n(D) The maximum absolute error in the difference of two quantities is the difference of their absolute errors.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"A is correct (trailing zeros after a decimal point are significant) and C is correct. B is wrong: 2.30 m = 2.30 × 10² cm keeps three figures. D is wrong: absolute errors add for both sums and differences. So only two are correct.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-units-measurement-22","question":"The quantity ½ε₀E², where E is an electric field, has the same dimensions as:","options":["force","pressure","energy","power"],"answer":1,"explanation":"½ε₀E² is the energy density of an electric field, energy per unit volume = [ML²T⁻²]/[L³] = [ML⁻¹T⁻²], which is the dimension of pressure (force per area), not of energy itself.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-23","question":"A force varies as F = a√x + bt², where x is distance and t is time. The dimensions of b/a are:","options":["[L^(1/2) T⁻²]","[L^(−1/2) T²]","[L^(1/2) T²]","[L T⁻²]"],"answer":0,"explanation":"Each term must be a force: a = F/L^(1/2) and b = F/T². So b/a = L^(1/2)/T² = [L^(1/2) T⁻²].","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-24","question":"Match the physical constant (List I) with its dimensional formula (List II). List I: (P) Stefan–Boltzmann constant σ; (Q) Boltzmann constant k; (R) coefficient of viscosity η; (S) surface tension. List II: (1) [MT⁻²]; (2) [ML⁻¹T⁻¹]; (3) [ML²T⁻²K⁻¹]; (4) [MT⁻³K⁻⁴].","options":["P-3, Q-4, R-2, S-1","P-1, Q-3, R-2, S-4","P-4, Q-3, R-1, S-2","P-4, Q-3, R-2, S-1"],"answer":3,"explanation":"σ = (W m⁻²)/K⁴ = [MT⁻³K⁻⁴]; k = J/K = [ML²T⁻²K⁻¹]; η from F = ηA dv/dx is [ML⁻¹T⁻¹]; surface tension = force/length = [MT⁻²].","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-25","question":"The length of a simple pendulum is measured as 50.0 cm using a scale of least count 1 mm, and the time for 50 oscillations is measured as 70 s with a watch of resolution 0.5 s. The maximum percentage error in the value of g obtained from these measurements is about:","options":["1.6%","2.4%","0.9%","1.4%"],"answer":0,"explanation":"g = 4π²L/T². ΔL/L = 0.1/50.0 = 0.2%; ΔT/T = 0.5/70 ≈ 0.71%. Δg/g = 0.2% + 2 × 0.71% ≈ 1.6%. Forgetting the factor 2 on the time term gives 0.9%.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-26","question":"Taking energy E, velocity v and time T as the fundamental quantities, the dimensional formula of surface tension is:","options":["[E² v⁻¹ T⁻¹]","[E v⁻² T⁻²]","[E v⁻¹ T⁻²]","[E v⁻² T⁻¹]"],"answer":1,"explanation":"Surface tension = [MT⁻²]. From E = [ML²T⁻²] and v = [LT⁻¹], mass = E/v², so [MT⁻²] = [E v⁻² T⁻²].","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-27","question":"Assertion (A): The number of significant figures in 3400 is ambiguous, but 3.400 × 10³ has four significant figures.\nReason (R): Trailing zeros in a number without a decimal point are always significant.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true: writing in scientific notation removes the ambiguity. R is false: trailing zeros in a number with no decimal point may or may not be significant, which is exactly why 3400 is ambiguous.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-units-measurement-28","question":"Magnetic flux divided by electrical resistance has the same dimensions as:","options":["electric charge","capacitance","inductance","electric current"],"answer":0,"explanation":"From Faraday's law emf = dΦ/dt, flux = volt × second. Then Φ/R = (V/R) × s = ampere × second = coulomb, the unit of charge.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-29","question":"A screw gauge of pitch 0.5 mm with 50 circular divisions has a zero error of −0.05 mm. When a wire is placed between the studs, the main-scale reading is 2.5 mm and the 20th circular division coincides with the reference line. The true diameter of the wire is:","options":["2.70 mm","3.50 mm","2.75 mm","2.65 mm"],"answer":2,"explanation":"LC = 0.5/50 = 0.01 mm. Observed = 2.5 + 20 × 0.01 = 2.70 mm. True = observed − zero error = 2.70 − (−0.05) = 2.75 mm; treating the negative error as positive gives 2.65 mm.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-30","question":"The resistivity of a wire is found from ρ = πr²R/L. The radius is measured as 0.25 mm with an error of 0.01 mm, the resistance with an error of 1% and the length with an error of 0.5%. The maximum percentage error in ρ is:","options":["5.5%","13.5%","4.5%","9.5%"],"answer":3,"explanation":"Δr/r = 0.01/0.25 = 4%, and r appears squared: 2 × 4% = 8%. Total = 8 + 1 + 0.5 = 9.5%. Taking the radius error only once gives 5.5%.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-units-measurement-31", "question": "The SI base unit of luminous intensity is the:", "options": ["lumen", "candela", "lux", "watt per steradian"], "answer": 1, "explanation": "Luminous intensity is one of the seven SI base quantities and its unit is the candela (cd). The lumen (luminous flux) and lux (illuminance) are derived units.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-units-measurement-32", "question": "Which of the following quantities is dimensionless?", "options": ["Stress", "Angular velocity", "Strain", "Pressure gradient"], "answer": 2, "explanation": "Strain is change in length divided by original length, a ratio of two lengths, so it has no dimensions. Angular velocity is [T⁻¹], not dimensionless, even though the radian itself is.", "difficulty": "easy", "source": "JEE Main · NEET"},
  {"id": "phy-units-measurement-33", "question": "A physical quantity has the dimensional formula [ML⁻¹T⁻²]. Its SI unit is the:", "options": ["joule", "newton", "watt", "pascal"], "answer": 3, "explanation": "Force per unit area: [MLT⁻²]/[L²] = [ML⁻¹T⁻²], which is pressure or stress, measured in pascal (N/m²).", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-units-measurement-34", "question": "Following the NCERT rule for rounding off, the numbers 2.745 and 2.735 rounded to three significant figures are respectively:", "options": ["2.75 and 2.74", "2.74 and 2.73", "2.74 and 2.74", "2.75 and 2.73"], "answer": 2, "explanation": "When the dropped digit is exactly 5, the preceding digit is left unchanged if it is even and raised by one if it is odd. So 2.745 → 2.74 (4 is even) and 2.735 → 2.74 (3 is odd, raised to 4).", "difficulty": "moderate", "source": "NEET · JEE Main"},
  {"id": "phy-units-measurement-35", "question": "In the relation 1/λ = R(1/n₁² − 1/n₂²) for the hydrogen spectrum, the dimensional formula of the Rydberg constant R is:", "options": ["[L]", "[T⁻¹]", "[L⁻¹]", "[ML²T⁻²]"], "answer": 2, "explanation": "The bracket holds pure numbers, so R has the dimensions of 1/λ, that is [L⁻¹]. It is often quoted in m⁻¹, not in hertz, which would be [T⁻¹].", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "phy-units-measurement-36", "question": "The dimensional formula of the permeability of free space μ₀ is:", "options": ["[MLT⁻²A⁻²]", "[ML²T⁻²A⁻¹]", "[M⁻¹L⁻³T⁴A²]", "[MLT⁻¹A⁻¹]"], "answer": 0, "explanation": "From the force per unit length between parallel currents, F/l = μ₀I₁I₂/(2πd), μ₀ = F/I² = [MLT⁻²A⁻²]. [M⁻¹L⁻³T⁴A²] is ε₀, and μ₀ε₀ = 1/c² checks: product = [L⁻²T²].", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "phy-units-measurement-37", "question": "The product 4.237 × 2.51, written to the correct number of significant figures, is:", "options": ["10.63", "10.635", "11", "10.6"], "answer": 3, "explanation": "4.237 × 2.51 = 10.635; a product keeps as many significant figures as the least precise factor, here three (2.51), so the result is 10.6.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-units-measurement-38", "question": "The dimensional formula of electric potential (the volt) is:", "options": ["[ML²T⁻²A⁻¹]", "[ML²T⁻³A⁻¹]", "[MLT⁻³A⁻¹]", "[ML²T⁻³A⁻²]"], "answer": 1, "explanation": "V = W/q = [ML²T⁻²]/[AT] = [ML²T⁻³A⁻¹]. [ML²T⁻³A⁻²] is resistance (V/A), a common slip.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "phy-units-measurement-39", "question": "In a system of units the unit of force is 100 N, the unit of length is 10 m and the unit of time is 100 s. The unit of mass in this system is:", "options": ["10⁵ kg", "10³ kg", "10⁴ kg", "10⁶ kg"], "answer": 0, "explanation": "Since F = M L T⁻², M = F T²/L = 100 × (100)²/10 kg = 10⁶/10 = 10⁵ kg.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "phy-units-measurement-40", "question": "Which of the following combinations of the electronic charge e, permittivity ε₀, Planck's constant h and speed of light c is dimensionless?", "options": ["e²/(ε₀hc)", "e²/(ε₀h)", "ε₀hc/e", "h/(ε₀ce²)"], "answer": 0, "explanation": "e²/ε₀ has the units of force × distance² (N m²), and hc has units J m = N m², so e²/(ε₀hc) is a pure number (it equals 2α, twice the fine-structure constant). e²/(ε₀h) has the dimensions of velocity, so it is not dimensionless.", "difficulty": "hard", "source": "JEE Main 2022 pattern"},
  {"id": "phy-units-measurement-41", "question": "The quantity √(μ₀/ε₀) has the same dimensions as:", "options": ["velocity", "capacitance", "inductance", "resistance"], "answer": 3, "explanation": "μ₀/ε₀ = [MLT⁻²A⁻²]/[M⁻¹L⁻³T⁴A²] = [M²L⁴T⁻⁶A⁻⁴], whose square root is [ML²T⁻³A⁻²], the dimensions of resistance (it is the 377 Ω impedance of free space). 1/√(μ₀ε₀), not √(μ₀/ε₀), is a velocity.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-units-measurement-42", "question": "The period T of the gravitational oscillation of a star is believed to depend only on its mean density ρ and the gravitational constant G. Dimensional analysis gives:", "options": ["T ∝ (Gρ)^(1/2)", "T ∝ (Gρ)^(−1/2)", "T ∝ G/ρ", "T ∝ (G/ρ)^(1/2)"], "answer": 1, "explanation": "Gρ = [M⁻¹L³T⁻²][ML⁻³] = [T⁻²], so the only combination with the dimension of time is (Gρ)^(−1/2).", "difficulty": "hard", "source": "JEE Advanced pattern"},
  {"id": "phy-units-measurement-43", "question": "The temperatures of two bodies are measured as (40 ± 0.3) °C and (20 ± 0.2) °C. The percentage error in their temperature difference is:", "options": ["1.75%", "0.5%", "2.5%", "1.25%"], "answer": 2, "explanation": "For a difference the absolute errors add: Δ = 20 °C ± (0.3 + 0.2) = 20 ± 0.5 °C, so the percentage error is 0.5/20 × 100 = 2.5%. Adding the percentage errors (0.75% + 1% = 1.75%) is valid only for products and quotients.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "phy-units-measurement-44", "question": "A quantity P = a³b²/(√c · d). The percentage errors in a, b, c and d are 1%, 2%, 3% and 4%. If P is calculated as 3.763, it should be reported as:", "options": ["3.763", "3.76", "3.8", "4"], "answer": 2, "explanation": "Maximum error = 3(1) + 2(2) + ½(3) + 4 = 12.5%, i.e. about 0.47 in 3.763. The first decimal place is already uncertain, so P should be rounded to 3.8.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "phy-units-measurement-45", "question": "The ratio h/e (Planck's constant divided by the electronic charge) has the same dimensions as:", "options": ["magnetic flux", "electric flux", "magnetic field", "electric potential"], "answer": 0, "explanation": "h/e has units J s/C = (J/C) s = V s, and one volt-second is one weber, the unit of magnetic flux (from Faraday's law, ε = dΦ/dt). Volt alone would need J/C without the second.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-units-measurement-46", "question": "Which of the following relations can NOT be obtained by the method of dimensions, even up to a dimensionless constant?", "options": ["T = 2π√(l/g) for a simple pendulum", "s = ut + ½at²", "v = √(T/μ) for waves on a string", "F = mv²/r for circular motion"], "answer": 1, "explanation": "Dimensional analysis can give a relation only when it is a single product of powers; s = ut + ½at² is a sum of two terms, so the method cannot produce it (though it is dimensionally consistent). The other three are single power-law products.", "difficulty": "hard", "source": "NEET · JEE Main"},
  {"id": "phy-units-measurement-47", "question": "The speed v of ripples on a liquid surface depends on the surface tension S, the density ρ and the wavelength λ. Using dimensional analysis, if λ is made 4 times (S and ρ unchanged), v becomes:", "options": ["half", "double", "one-fourth", "four times"], "answer": 0, "explanation": "Matching dimensions gives v ∝ √(S/(ρλ)), since S/(ρλ) = [MT⁻²]/[ML⁻²] = [L²T⁻²]. So v ∝ λ^(−1/2), and λ → 4λ halves v.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-units-measurement-48", "question": "The quantity GM/c², where G is the gravitational constant, M a mass and c the speed of light, has the dimensions of:", "options": ["time", "mass", "length", "velocity"], "answer": 2, "explanation": "GM = [M⁻¹L³T⁻²][M] = [L³T⁻²]; dividing by c² = [L²T⁻²] leaves [L]. (2GM/c² is the Schwarzschild radius.) GM/c³ would be a time.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-units-measurement-49", "question": "How many of the following statements are correct?\n(A) Random errors can be reduced by taking the mean of a large number of observations.\n(B) A zero error in an instrument is a systematic error.\n(C) Relative error is a dimensionless quantity.\n(D) Precision refers to how close a measured value is to the true value.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, B and C are correct. D is wrong: closeness to the true value is accuracy, while precision is the resolution or the closeness of repeated readings to one another.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-units-measurement-50", "question": "Assertion (A): Strain has no dimensions, while stress has the same dimensions as pressure.\nReason (R): Young's modulus has the same dimensions as stress.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 1, "explanation": "Both statements are true: strain is a ratio of lengths and stress is force per area like pressure, and Y = stress/strain carries the dimensions of stress. But R is a consequence of A, not the reason why strain is dimensionless or stress is like pressure.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-units-measurement-51", "question": "Match the SI unit (List I) with its dimensional formula (List II). List I: (P) tesla; (Q) weber; (R) henry; (S) farad. List II: (1) [ML²T⁻²A⁻²]; (2) [MT⁻²A⁻¹]; (3) [M⁻¹L⁻²T⁴A²]; (4) [ML²T⁻²A⁻¹].", "options": ["P-4, Q-2, R-1, S-3", "P-2, Q-4, R-3, S-1", "P-2, Q-4, R-1, S-3", "P-1, Q-4, R-2, S-3"], "answer": 2, "explanation": "Tesla: B = F/(qv) = [MT⁻²A⁻¹]; weber = T m² = [ML²T⁻²A⁻¹]; henry = V s/A = [ML²T⁻²A⁻²]; farad = C/V = [M⁻¹L⁻²T⁴A²]. So P-2, Q-4, R-1, S-3.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-units-measurement-52", "question": "The object distance and image distance for a convex lens are measured as u = (30.0 ± 0.3) cm and v = (60.0 ± 0.6) cm (magnitudes). The focal length with its maximum error is:", "options": ["(20.0 ± 0.9) cm", "(20.0 ± 0.2) cm", "(20.0 ± 0.3) cm", "(20.0 ± 0.1) cm"], "answer": 1, "explanation": "f = uv/(u + v) = 1800/90 = 20.0 cm. From 1/f = 1/u + 1/v, Δf/f² = Δu/u² + Δv/v², so Δf = 400(0.3/900 + 0.6/3600) = 400 × 0.0005 = 0.2 cm. Simply adding relative errors of u, v and (u + v) overestimates it (≈ 0.9 cm).", "difficulty": "very-hard", "source": "JEE Main 2021 pattern"},
  {"id": "phy-units-measurement-53", "question": "G. I. Taylor estimated that the radius R of the fireball of an explosion at time t depends only on the energy released E, the time t and the density ρ of air. On this basis, if the energy of the explosion were 32 times larger, the radius at the same instant would be:", "options": ["32 times", "√32 times", "4 times", "2 times"], "answer": 3, "explanation": "Et²/ρ = [ML²T⁻²][T²]/[ML⁻³] = [L⁵], so R ∝ (Et²/ρ)^(1/5). Multiplying E by 32 multiplies R by 32^(1/5) = 2.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "phy-units-measurement-54", "question": "How many of the following pairs have identical dimensions?\n(A) Reynolds number and strain\n(B) Light year and wavelength\n(C) Impulse and torque\n(D) RC and LC (R = resistance, L = inductance, C = capacitance)", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "A (both dimensionless) and B (both lengths) match. Impulse is [MLT⁻¹] but torque is [ML²T⁻²]; RC is a time [T] while LC is [T²] (since 1/√(LC) is an angular frequency).", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "phy-units-measurement-55", "question": "A screw gauge has a pitch of 1 mm and 100 circular divisions. With the studs touching, the zero of the circular scale is 4 divisions below the reference line (a positive zero error). For a steel ball, the main-scale reading is 5 mm and the 54th division coincides. The maximum percentage error in the calculated volume of the ball (error = one least count) is about:", "options": ["0.18%", "0.55%", "0.36%", "1.09%"], "answer": 1, "explanation": "Least count = 1 mm/100 = 0.01 mm; zero error = +0.04 mm, so d = 5.54 − 0.04 = 5.50 mm. Volume ∝ d³, so % error = 3 × 0.01/5.50 × 100 ≈ 0.55%.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-units-measurement-56", "question": "How many of the following statements about the revised SI (in force since 2019) are correct?\n(A) The kilogram is defined by fixing the numerical value of Planck's constant h.\n(B) The ampere is defined by fixing the numerical value of the elementary charge e.\n(C) The kelvin is defined by fixing the numerical value of the Boltzmann constant k.\n(D) The second is defined using the caesium-133 hyperfine transition frequency of 9,192,631,770 Hz.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct: since 2019 the kg, A, K and mol are tied to fixed values of h, e, k and N_A, while the second still uses the Cs-133 transition and the metre the fixed value of c. The kelvin is no longer defined through the triple point of water.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-units-measurement-57", "question": "If L is a length, ΔV a potential difference and Δt a time interval, the quantity ε₀L(ΔV/Δt) has the dimensions of:", "options": ["charge", "current", "voltage", "resistance"], "answer": 1, "explanation": "ε₀ × length has the dimensions of capacitance (C = ε₀A/d), and capacitance × voltage is charge; charge divided by time is current. This is the form of the displacement current.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-units-measurement-58", "question": "By dimensional analysis the speed of sound in a gas depends only on its pressure P and density ρ. If the pressure of the gas is doubled at constant temperature, the speed of sound:", "options": ["becomes √2 times", "is unchanged", "becomes 2 times", "becomes 1/√2 times"], "answer": 1, "explanation": "Dimensions give v = k√(P/ρ). At constant temperature P/ρ = RT/M is constant (Boyle's law), so doubling P doubles ρ too and v does not change; √2 ignores the change in density.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "phy-units-measurement-59", "question": "A vernier callipers has 10 vernier divisions equal to 9 main-scale divisions of 1 mm each. With the jaws closed, the zero of the vernier lies to the left of the main-scale zero and its 7th division coincides with a main-scale mark. While measuring a rod, the main-scale reading is 31 mm and the 4th vernier division coincides. The true length of the rod is:", "options": ["3.11 cm", "3.21 cm", "3.07 cm", "3.17 cm"], "answer": 3, "explanation": "Least count = 0.1 mm. Vernier zero to the left means a negative zero error = −(10 − 7) × 0.1 = −0.3 mm. Observed reading = 31.4 mm, so true length = 31.4 − (−0.3) = 31.7 mm = 3.17 cm.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-units-measurement-60", "question": "The unit of mass is doubled, the unit of length is halved and the unit of time is doubled. The numerical value of a given power, expressed in the new units, becomes:", "options": ["1/16 of its old value", "16 times its old value", "4 times its old value", "1/4 of its old value"], "answer": 1, "explanation": "Power = [ML²T⁻³], so the new unit of power = 2 × (½)² × (2)⁻³ = 1/16 of the old unit. A smaller unit means a larger number: n₂ = n₁ × 16. The answer 1/16 confuses the size of the unit with the numerical value.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-units-measurement-61","question":"A vernier callipers has main-scale divisions of 0.5 mm, and 25 vernier divisions span 24 main-scale divisions. With the jaws closed, the vernier zero lies to the right of the main-scale zero and the 3rd vernier division coincides. For a hollow tube, the external jaws give a main-scale reading of 31.0 mm with the 7th vernier division coinciding, and the internal jaws give 24.5 mm with the 13th division coinciding. The wall thickness of the tube is:","options":["3.19 mm","3.13 mm","3.16 mm","6.38 mm"],"answer":0,"explanation":"Least count = 0.5/25 = 0.02 mm. External diameter (observed) = 31.0 + 7 × 0.02 = 31.14 mm; internal = 24.5 + 13 × 0.02 = 24.76 mm. Both jaws ride on the same slider, so the +0.06 mm zero error is the same in both readings and cancels in the difference: thickness = (31.14 − 24.76)/2 = 3.19 mm. Correcting only one reading (3.16 mm) or subtracting from one and adding to the other (3.13 mm) are the traps, and 6.38 mm forgets that the difference of diameters is twice the wall.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-62","question":"The internal diameter and depth of a cylindrical beaker are measured with a vernier callipers of least count 0.01 cm (zero error already corrected) as 4.00 cm and 5.00 cm. The volume of the beaker, with its maximum error, should be reported as:","options":["(62.8 ± 0.3) cm³","(62.8 ± 0.4) cm³","(62.8 ± 0.1) cm³","(62.8 ± 0.6) cm³"],"answer":1,"explanation":"V = πD²h/4 = π × 16 × 5/4 = 62.8 cm³. ΔV/V = 2ΔD/D + Δh/h = 2(0.01/4.00) + 0.01/5.00 = 0.005 + 0.002 = 0.7%, so ΔV = 0.007 × 62.8 ≈ 0.44 cm³ → (62.8 ± 0.4) cm³. Forgetting the factor 2 on the diameter gives 0.45% and ±0.3 cm³.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-63","question":"The circular scale of a screw gauge has 50 divisions, and the spindle advances 1 mm when the circular scale is turned through two complete rotations. With nothing between the studs, the reference line reads +4 circular divisions. For a wire, the main-scale reading is 2.5 mm and the circular-scale reading is 37. The diameter of the wire is:","options":["2.91 mm","2.87 mm","2.83 mm","3.16 mm"],"answer":2,"explanation":"Pitch = 1 mm/2 = 0.5 mm, so least count = 0.5/50 = 0.01 mm. Zero error = +4 × 0.01 = +0.04 mm. Observed = 2.5 + 37 × 0.01 = 2.87 mm; true = 2.87 − 0.04 = 2.83 mm. Taking the pitch as 1 mm gives 3.16 mm; adding the zero error gives 2.91 mm; ignoring it gives 2.87 mm.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-64","question":"The diameter of a resistance wire is measured with a screw gauge (least count 0.01 mm) at five places as 0.50, 0.53, 0.47, 0.52 and 0.48 mm. Its resistance is (5.0 ± 0.1) Ω and its length (50.0 ± 0.1) cm. Using the mean absolute error for the diameter, the maximum percentage error in the resistivity ρ = πd²R/(4L) is:","options":["6.2%","14.2%","8.2%","10.2%"],"answer":3,"explanation":"Mean d = 0.50 mm; absolute deviations 0, 0.03, 0.03, 0.02, 0.02 give a mean absolute error of 0.02 mm (larger than the least count, so it is the one used), i.e. 4%. Δρ/ρ = 2(4%) + 0.1/5.0 + 0.1/50.0 = 8% + 2% + 0.2% = 10.2%. Forgetting the square gives 6.2%; using the largest deviation (6% each) gives 14.2%.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-units-measurement-65", "question": "How many of the following statements about the vernier callipers and the screw gauge are correct?\n(A) Backlash error in a screw gauge is reduced by always turning the screw in the same direction while taking a reading.\n(B) If, with the jaws closed, the vernier zero lies to the right of the main-scale zero, the zero error is positive and is subtracted from every observed reading.\n(C) The least count of a screw gauge equals its pitch multiplied by the number of circular-scale divisions.\n(D) The ratchet of a screw gauge makes the studs press the object with the same small force every time.", "options": ["Only one", "Only three", "Only two", "All four"], "answer": 1, "explanation": "A, B and D are correct. C is wrong: least count = pitch ÷ number of circular divisions (for example 0.5 mm/50 = 0.01 mm), not the product.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-units-measurement-66", "question": "In a study of energy dissipation in a simple pendulum, the amplitude falls from 8 cm to 4 cm in 60 s, and the damping is such that the amplitude decays exponentially with time. The time after which the energy of oscillation becomes 1/16 of its initial value (measured from the start) is:", "options": ["240 s", "60 s", "480 s", "120 s"], "answer": 3, "explanation": "Energy ∝ A². The amplitude halves every 60 s, so the energy falls to 1/4 every 60 s; 1/16 = (1/4)² needs 2 × 60 = 120 s. Taking the energy to halve every 60 s (treating E like A) gives 240 s.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-units-measurement-67", "question": "A student studies the damping of a simple pendulum by recording its amplitude A at regular time intervals. How many of the following statements are correct?\n(A) A graph of A² against time t is a straight line with a negative slope.\n(B) A graph of ln(A²) against t is a straight line whose slope has twice the magnitude of the slope of the ln A against t graph.\n(C) The time in which the energy halves is half the time in which the amplitude halves.\n(D) For a heavier bob of the same size and shape, the amplitude dies out more slowly.", "options": ["Only three", "Only one", "Only two", "All four"], "answer": 0, "explanation": "With linear drag A = A₀e^(−bt/2m), so A² = A₀²e^(−bt/m): an exponential, not a straight line, so A is wrong; ln A² = 2 ln A makes B correct. E halves when A falls to A₀/√2, which takes half the amplitude-halving time, so C is correct. The same size gives the same b, and the decay constant b/2m is smaller for larger m, so D is correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-units-measurement-68","question":"A simple pendulum has a bob of mass 200 g on a string 1.0 m long (g = 10 m/s²). While it swings, the square of its (small) linear amplitude falls from 16 cm² to 9 cm². The mechanical energy dissipated during this interval is:","options":["0.7 mJ","0.35 mJ","1.4 mJ","7 mJ"],"answer":0,"explanation":"For small oscillations E = ½mω²A² with ω² = g/L, so E = mgA²/(2L). ΔE = (0.2 × 10/(2 × 1.0)) × (16 − 9) × 10⁻⁴ = 1 × 7 × 10⁻⁴ J = 0.7 mJ. Dropping the ½ gives 1.4 mJ; a slip converting cm² to m² gives 7 mJ.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-69","question":"In a pendulum experiment the length l is measured from the point of suspension to the top of the bob, so the bob's radius is left out. A graph of T² against l passes through (40.0 cm, 1.64 s²) and (90.0 cm, 3.64 s²). The value of g and the radius of the bob are:","options":["g = 9.63 m/s² and radius = 0","g = π² m/s² ≈ 9.87 m/s² and radius = 1.0 cm","g = 9.63 m/s² and radius = 1.0 cm","g = π² m/s² ≈ 9.87 m/s² and radius = 0.5 cm"],"answer":1,"explanation":"T² = (4π²/g)(l + r). Slope = (3.64 − 1.64)/(0.90 − 0.40) = 4.00 s²/m, so g = 4π²/4 = π² ≈ 9.87 m/s²; the omitted radius only shifts the line. T² = 0 at l = 0.40 − 1.64/4 = −0.01 m, so r = 1.0 cm. Using a single point, g = 4π²(0.40)/1.64 = 9.63 m/s², which carries the error from the missing radius.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-70","question":"A metre scale balances on a knife-edge at its 49.0 cm mark. When a 20 g mass is hung at the 10.0 cm mark, the scale balances at the 39.0 cm mark. The mass of the metre scale is:","options":["52.7 g","20 g","58 g","72.5 g"],"answer":2,"explanation":"Without the load the centre of gravity is at 49.0 cm. Taking moments about the new knife-edge (39.0 cm): 20 × (39.0 − 10.0) = M × (49.0 − 39.0), so M = 580/10 = 58 g. Assuming the centre of gravity is at 50 cm gives 580/11 = 52.7 g.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-71","question":"A non-uniform metre scale of unknown mass M has its centre of gravity at an unknown mark x. With a 100 g mass hung at the 20 cm mark, it balances on a knife-edge at 40 cm; with the same mass moved to the 90 cm mark, it balances at 60 cm. The mass of the scale is:","options":["200 g","300 g","125 g","250 g"],"answer":3,"explanation":"Moments: 100(40 − 20) = M(x − 40) and 100(90 − 60) = M(60 − x). Adding: 2000 + 3000 = M × 20, so M = 250 g (and x = 40 + 2000/250 = 48 cm). Assuming x = 50 cm gives 200 g from the first balance and 300 g from the second, which is why both are needed.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-units-measurement-72", "question": "In Searle's experiment a wire 2.00 m long (length error ±0.1 cm) has a diameter of 0.40 mm measured with a screw gauge of least count 0.01 mm. An extra load of 2.0 kg (exact) produces an extension of 1.60 mm read on a micrometer of least count 0.01 mm (g = 10 m/s²). The Young's modulus and its maximum percentage error are about:", "options": ["2.0 × 10¹¹ N/m², 5.7%", "2.0 × 10¹¹ N/m², 3.2%", "5.0 × 10¹⁰ N/m², 5.7%", "8.0 × 10¹¹ N/m², 3.2%"], "answer": 0, "explanation": "Y = FL/(πd²/4 · Δl) = (20 × 2.00)/(π × 0.04 × 10⁻⁶ × 1.60 × 10⁻³) ≈ 1.99 × 10¹¹ N/m². ΔY/Y = 2(0.01/0.40) + 0.01/1.60 + 0.1/200 = 5% + 0.625% + 0.05% ≈ 5.7%. Forgetting the square on d gives 3.2%; using the diameter as the radius in the area gives 5.0 × 10¹⁰ N/m².", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-units-measurement-73", "question": "How many of the following statements about determining Young's modulus by Searle's method are correct?\n(A) The reference wire, of the same material, cancels the effects of temperature change and of any yielding of the support.\n(B) If extension is plotted on the y-axis against load on the x-axis, Young's modulus is directly proportional to the slope of the graph.\n(C) Readings are taken both while loading and while unloading, and their mean is used, to allow for elastic lag.\n(D) For the same load, a thicker wire of the same material and length gives a larger extension.", "options": ["Only two", "Only one", "Only three", "All four"], "answer": 0, "explanation": "A and C are correct. Extension = (L/AY) × load, so the slope is L/(AY) and Y is inversely proportional to it: B is wrong. A thicker wire has a larger A and so a smaller extension: D is wrong.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-units-measurement-74","question":"The bore of a capillary tube is viewed through a travelling microscope: the left and right inner edges read 3.215 cm and 3.255 cm. Water (contact angle 0°, density 1000 kg/m³) rises in it, and the microscope readings for the bottom of the meniscus and for the outside water surface are 8.62 cm and 1.12 cm. The surface tension of water from this data is (g = 10 m/s²):","options":["0.150 N/m","0.075 N/m","0.0375 N/m","0.30 N/m"],"answer":1,"explanation":"Inner diameter = 3.255 − 3.215 = 0.040 cm, so r = 0.020 cm = 2 × 10⁻⁴ m; h = 8.62 − 1.12 = 7.50 cm. T = rhρg/(2 cos θ) = (2 × 10⁻⁴ × 0.075 × 1000 × 10)/2 = 0.075 N/m. Using the diameter as the radius doubles it to 0.150 N/m.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-75","question":"Water rises to 4.8 cm in a clean glass capillary. A detergent that lowers the surface tension of water by 25% is dissolved in it, with negligible change in density and contact angle. The new capillary rise in the same tube is:","options":["6.0 cm","1.2 cm","3.6 cm","6.4 cm"],"answer":2,"explanation":"h = 2T cos θ/(rρg) ∝ T for the same tube and liquid density, so h′ = 0.75 × 4.8 = 3.6 cm. The value 6.4 cm (= 4.8/0.75) comes from inverting the proportion.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id": "phy-units-measurement-76", "question": "How many of the following statements are correct?\n(A) Detergent molecules collect at a water surface with their water-repelling ends outward, which lowers the surface tension.\n(B) Dissolving a detergent in water lowers its capillary rise in a clean glass tube.\n(C) A detergent removes grease because it increases the angle of contact between water and the greasy fabric.\n(D) The capillary rise of water in a tube is greater when the tube is in a lift accelerating upward than when the lift is at rest.", "options": ["Only one", "Only three", "All four", "Only two"], "answer": 3, "explanation": "A and B are correct (h ∝ T). C is wrong: detergents lower the contact angle so water wets the greasy fabric. D is wrong: in a lift accelerating upward g_eff = g + a, so h = 2T cos θ/(rρg_eff) is smaller.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-units-measurement-77","question":"A steel ball of radius 1.0 mm (density 7800 kg/m³) takes 10.0 s to fall at its terminal speed between two marks 20.0 cm apart in glycerine (density 1260 kg/m³). The coefficient of viscosity of glycerine is about (g = 10 m/s²):","options":["0.87 Pa s","0.36 Pa s","2.9 Pa s","0.73 Pa s"],"answer":3,"explanation":"v = 0.200/10.0 = 0.020 m/s. η = 2r²(ρ − σ)g/(9v) = 2 × 10⁻⁶ × 6540 × 10/(9 × 0.020) ≈ 0.73 Pa s. Ignoring the buoyancy (using 7800) gives 0.87 Pa s; using the diameter as the radius gives 2.9 Pa s.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "phy-units-measurement-78", "question": "How many of the following statements about the falling-ball method for viscosity are correct?\n(A) Timing begins only after the ball has fallen some distance into the liquid, so that it moves at its terminal speed between the marks.\n(B) A ball of the same material with twice the radius takes one-quarter of the time to fall between the same two marks.\n(C) The terminal speed does not depend on the density of the liquid.\n(D) The tube should be wide compared with the ball, because nearby walls increase the drag on it.", "options": ["Only three", "Only one", "Only two", "All four"], "answer": 0, "explanation": "A, B and D are correct: v = 2r²(ρ − σ)g/9η ∝ r², so doubling r makes v four times and the time one-quarter. C is wrong, because the liquid's density σ appears through the buoyancy term (ρ − σ).", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-units-measurement-79","question":"A resonance tube of internal diameter 5.0 cm is used with a 480 Hz tuning fork, and sound travels at 336 m/s in the tube. Taking the end correction as 0.3 times the diameter, the first resonance occurs at 16.0 cm of air column. The second resonance will occur at an air-column length of:","options":["51.0 cm","52.5 cm","49.5 cm","48.0 cm"],"answer":0,"explanation":"λ = 336/480 = 70 cm. e = 0.3 × 5.0 = 1.5 cm, and l₁ + e = λ/4 = 17.5 cm (so l₁ = 16.0 cm checks). Second resonance: l₂ + e = 3λ/4 = 52.5 cm, so l₂ = 51.0 cm = 3l₁ + 2e. Ignoring the end correction gives 3l₁ = 48.0 cm; forgetting to subtract e gives 52.5 cm.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-80","question":"With a 450 Hz tuning fork, the first two resonances in a resonance tube occur at air columns of 18.0 cm and 55.5 cm. Taking the end correction as 0.3 times the internal diameter, the internal diameter of the tube and the length of air column for the third resonance are:","options":["1.25 cm and 93.0 cm","2.5 cm and 93.0 cm","2.5 cm and 91.5 cm","5.0 cm and 92.25 cm"],"answer":1,"explanation":"λ/2 = 55.5 − 18.0 = 37.5 cm, so λ = 75 cm. e = (l₂ − 3l₁)/2 = (55.5 − 54.0)/2 = 0.75 cm, so d = 0.75/0.3 = 2.5 cm. The third resonance is another λ/2 further: 55.5 + 37.5 = 93.0 cm. Taking 0.3 × radius gives 1.25 cm, the trap.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-units-measurement-81", "question": "A 200 g metal block at 100 °C is dropped into 160 g of water at 20 °C held in a copper calorimeter of mass 70 g (specific heat of copper 400 J/kg K, of water 4200 J/kg K). The final steady temperature is 30 °C. Neglecting heat loss, the specific heat of the metal is:", "options": ["480 J/kg K", "437.5 J/kg K", "500 J/kg K", "520 J/kg K"], "answer": 2, "explanation": "Heat gained = 0.16 × 4200 × 10 + 0.07 × 400 × 10 = 6720 + 280 = 7000 J. Heat lost = 0.2 × c × (100 − 30) = 14c, so c = 500 J/kg K. Ignoring the calorimeter gives 480; using the drop 100 − 20 = 80 °C gives 437.5.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id":"phy-units-measurement-82","question":"To find the specific heat of a liquid by the method of mixtures, a 300 g copper block (specific heat 400 J/kg K) at 100 °C is dropped into 200 g of the liquid at 25 °C in a calorimeter whose water equivalent is 20 g (specific heat of water 4200 J/kg K). The final temperature is 40 °C. The specific heat of the liquid is:","options":["1560 J/kg K","2400 J/kg K","2360 J/kg K","1980 J/kg K"],"answer":3,"explanation":"Heat lost by copper = 0.3 × 400 × 60 = 7200 J. Heat gained = (0.2c + 0.020 × 4200) × 15, so 0.2c + 84 = 480 and c = 1980 J/kg K. Ignoring the calorimeter gives 2400; treating the 20 g water equivalent as 20 g of copper (heat capacity 8 J/K) gives 2360.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-units-measurement-83", "question": "How many of the following statements about finding the specific heat of a solid by the method of mixtures are correct?\n(A) The hot solid is transferred to the calorimeter as quickly as possible.\n(B) The calorimeter is polished on the outside and kept in an insulating jacket to reduce heat loss.\n(C) The temperature recorded as the final temperature is the lowest temperature shown by the thermometer after mixing.\n(D) Heat lost while transferring the hot solid makes the calculated specific heat of the solid lower than its true value.", "options": ["Only one", "Only two", "All four", "Only three"], "answer": 3, "explanation": "A, B and D are correct. In D, the solid actually enters below the recorded 100 °C, so the water gains less heat than assumed for that temperature drop and c comes out low. C is wrong: the mixture warms up, and the maximum temperature reached is recorded.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-units-measurement-84","question":"In a metre bridge, 4 Ω is placed in the left gap and 6 Ω in the right gap, and the null point is at 40.3 cm from the left end. When the two resistors are interchanged, the null point is at 60.7 cm. Taking end corrections α at the left end and β at the right end of the wire, α and β are:","options":["α = 0.5 cm, β = 1.5 cm","α = 1.5 cm, β = 0.5 cm","α = β = 1.0 cm","α = β = 0.4 cm"],"answer":0,"explanation":"4/6 = (40.3 + α)/(59.7 + β) gives 3α − 2β = −1.5; 6/4 = (60.7 + α)/(39.3 + β) gives 2α − 3β = −3.5. Solving: α = 0.5 cm, β = 1.5 cm. With no end error the two null points would add up to exactly 100 cm; here they add to 101.0 cm.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-units-measurement-85", "question": "A resistance wire is placed in the right gap of a metre bridge with a standard 2 Ω in the left gap, and the null point is found at 40.0 cm, located to ±0.1 cm. The resistance of the wire and the percentage error in it caused by the uncertainty in the null point are:", "options": ["3.0 Ω and 0.25%", "3.0 Ω and 0.42%", "1.33 Ω and 0.42%", "3.0 Ω and 0.17%"], "answer": 1, "explanation": "X = 2 × (100 − 40)/40 = 3.0 Ω. X ∝ (100 − l)/l, so ΔX/X = Δl/l + Δl/(100 − l) = 0.1/40 + 0.1/60 ≈ 0.42%. Using only one of the two terms gives 0.25% or 0.17%; 1.33 Ω swaps the ratio. The error is smallest when the null point is near the middle of the wire.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-units-measurement-86","question":"A resistor of true value 100 Ω is measured with a voltmeter of resistance 1000 Ω and an ammeter of resistance 2 Ω. Which connection gives the more accurate result, and what is its percentage error?","options":["Voltmeter directly across the resistor: −9.1%","Voltmeter directly across the resistor: −10%","Ammeter in series with the resistor and the voltmeter across both: +2%","Ammeter in series with the resistor and the voltmeter across both: −2%"],"answer":2,"explanation":"Voltmeter across R alone: measured R = 100 × 1000/1100 = 90.9 Ω, an error of −9.1%. Voltmeter across ammeter + R: measured R = 100 + 2 = 102 Ω, an error of +2%. The second is better; its error is positive because the ammeter's resistance is added. The −10% option uses R/R_V instead of R/(R + R_V).","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-87","question":"In the Ohm's law experiment the ammeter has resistance 2 Ω and the voltmeter 1000 Ω. For what value of the resistance being measured do the two connections (voltmeter directly across the resistor, or voltmeter across the ammeter and resistor together) give the same magnitude of percentage error?","options":["About 1002 Ω","About 22.4 Ω","About 501 Ω","About 45.7 Ω"],"answer":3,"explanation":"Voltmeter across R: |error| = R/(R + R_V). Voltmeter across both: error = R_A/R. Equating: R² = R_A(R + R_V), so R² − 2R − 2000 = 0, giving R = 1 + √2001 ≈ 45.7 Ω (close to √(R_A R_V)). Larger resistances are measured better with the voltmeter across both.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-88","question":"In an Ohm's law experiment the voltmeter has a range 0–3 V with 30 divisions and the ammeter a range 0–1 A with 50 divisions. The readings are 2.4 V and 0.60 A. Taking each instrument's least count as its error, the maximum percentage error in the resistance is:","options":["7.5%","3.3%","4.2%","0.8%"],"answer":0,"explanation":"Least counts: 3/30 = 0.1 V and 1/50 = 0.02 A. ΔR/R = 0.1/2.4 + 0.02/0.60 = 4.17% + 3.33% = 7.5%. Errors in a quotient add; quoting only one meter's error gives 4.2% or 3.3%.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-89","question":"In the half-deflection method a galvanometer shows a deflection θ with a resistance R = 2000 Ω in series with the cell. When a shunt S = 40 Ω is connected across the galvanometer, with R unchanged, the deflection becomes θ/2. The resistance of the galvanometer is about:","options":["40.0 Ω","40.8 Ω","80.0 Ω","39.2 Ω"],"answer":1,"explanation":"G = RS/(R − S) = 2000 × 40/1960 ≈ 40.8 Ω. Taking G = S (40 Ω) is only the limiting case R ≫ G; 39.2 Ω comes from RS/(R + S).","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-90","question":"In finding the figure of merit of a galvanometer of resistance 50 Ω, a cell of emf 2.0 V (negligible internal resistance) and a series resistance of 4950 Ω produce a deflection of 25 divisions. The galvanometer has 30 divisions on each side. The resistance that must be put in series with it to make a voltmeter of range 0–5 V is about:","options":["10.42 kΩ","12.45 kΩ","10.37 kΩ","9.95 kΩ"],"answer":2,"explanation":"I = 2.0/(4950 + 50) = 0.4 mA, so the figure of merit k = 0.4 mA/25 = 16 μA per division. Full-scale current = 30 × 16 = 480 μA. Series R = 5/(480 × 10⁻⁶) − 50 = 10 417 − 50 ≈ 10 367 Ω. Forgetting to subtract G gives 10.42 kΩ; using 25 divisions as full scale gives 12.45 kΩ.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-units-measurement-91", "question": "Assertion (A): In the half-deflection method, the galvanometer resistance G can be taken equal to the shunt resistance S that halves the deflection only when the series resistance R is much larger than G.\nReason (R): The relation assumes that connecting the shunt leaves the current drawn from the cell practically unchanged.", "options": ["Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "Both A and R are true, and R is the correct explanation of A", "A is false but R is true"], "answer": 2, "explanation": "The exact result is G = RS/(R − S). Only if R ≫ G does adding the shunt barely change the total current, so the current divides equally between G and S at half deflection, giving G ≈ S. R is exactly the reason for A.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-units-measurement-92","question":"On an optical bench, a knitting needle of length 20.0 cm placed between the lens and the object needle shows a separation of 20.6 cm on the bench scale. The object and image needles are then read on the bench scale at 30.6 cm and 60.6 cm from the lens. The focal length of the lens after the index correction is:","options":["19.6 cm","20.3 cm","20.6 cm","20.0 cm"],"answer":3,"explanation":"Index correction = 20.0 − 20.6 = −0.6 cm for every distance read on the scale, so u = 30.0 cm and v = 60.0 cm. 1/f = 1/30 + 1/60 = 1/20, so f = 20.0 cm. Using the uncorrected readings gives 30.6 × 60.6/91.2 ≈ 20.3 cm.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "phy-units-measurement-93", "question": "How many of the following statements about u–v data for a convex lens and a concave mirror (distances as magnitudes) are correct?\n(A) For a convex lens, the graph of v against u is a rectangular hyperbola with asymptotes u = f and v = f.\n(B) For a convex lens, the graph of 1/v against 1/u is a straight line of slope −1 whose intercepts on both axes equal 1/f.\n(C) For a concave mirror, the u–v graph meets the line v = u at the point (f, f).\n(D) In the parallax method, the image is located when there is no relative shift between it and the image needle as the eye moves sideways.", "options": ["Only three", "Only one", "Only two", "All four"], "answer": 0, "explanation": "A, B and D are correct. With magnitudes, 1/v + 1/u = 1/f, which gives B and the hyperbola of A. For a real image, v = u happens only at u = v = 2f (the centre of curvature), not at (f, f), so C is wrong.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-units-measurement-94","question":"To find the focal length of a convex mirror, a convex lens on an optical bench at the 50.0 cm mark forms a real image of an object needle at the 90.0 cm mark. The convex mirror is then placed between the lens and that image, and the image of the object needle coincides with the needle itself when the mirror is at the 70.0 cm mark. The focal length of the convex mirror is:","options":["10.0 cm","40.0 cm","20.0 cm","5.0 cm"],"answer":0,"explanation":"When the image falls back on the object, the rays meet the convex mirror normally, so they were heading for its centre of curvature, the point where the lens alone formed the image (90.0 cm). R = 90.0 − 70.0 = 20.0 cm, so f = R/2 = 10.0 cm. Quoting 20.0 cm confuses R with f; 40.0 cm uses the lens-to-mirror distance.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-units-measurement-95", "question": "A needle in front of a concave mirror coincides with its own inverted image, with no parallax, when it is 36.0 cm from the mirror. If the needle is moved to 27.0 cm from the mirror, its image is formed:", "options": ["54.0 cm behind the mirror, virtual", "54.0 cm in front of the mirror, real and twice the size", "10.8 cm in front of the mirror, real", "108 cm in front of the mirror, real"], "answer": 1, "explanation": "An object coincides with its own inverted image at the centre of curvature, so R = 36.0 cm and f = 18.0 cm. With u = 27.0 cm: 1/v = 1/18 − 1/27 = 1/54, so v = 54.0 cm, real, magnification −2. The 10.8 cm option comes from adding the reciprocals instead of subtracting.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id":"phy-units-measurement-96","question":"In an i–δ experiment with an equilateral glass prism, the angles of incidence 42° and 62° are found to give the same angle of deviation. Which statement is correct?","options":["The deviation is 52°, and the minimum deviation occurs at i = 52°","The deviation is 44°, and the minimum deviation is less than 44°","The deviation is 44°, and the minimum deviation occurs at i = 42°","The deviation is 20°, and it is the minimum deviation"],"answer":1,"explanation":"Equal deviations at i₁ and i₂ mean that i₂ is the emergence angle for i₁ (reversibility), so δ = i₁ + i₂ − A = 42 + 62 − 60 = 44°. Minimum deviation lies between them (where i = e), so δ_min < 44° (about 42° for the μ ≈ 1.56 these angles imply). 52° is just the average of the angles; 20° is their difference.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-97","question":"From the i–δ graph of a prism, the minimum deviation is 38° and it occurs at an angle of incidence of 49°. The angle of the prism and its refractive index are (sin 49° = 0.755):","options":["60° and 2.32","38° and 1.51","60° and 1.51","49° and 1.23"],"answer":2,"explanation":"At minimum deviation i = e, so A + δ_min = 2i, giving A = 98° − 38° = 60°, and r = A/2 = 30°. μ = sin 49°/sin 30° = 0.755/0.5 ≈ 1.51. The 2.32 option uses r = i − 30° = 19°.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-98","question":"A travelling microscope is focused on a mark on the table (reading 2.152 cm). A glass slab is placed over the mark, and the microscope is raised to refocus on the mark (reading 2.952 cm). Finally it is focused on lycopodium powder sprinkled on the top surface of the slab (reading 4.552 cm). The refractive index of the glass is:","options":["1.33","3.00","0.67","1.50"],"answer":3,"explanation":"Real thickness = 4.552 − 2.152 = 2.400 cm; apparent thickness = 4.552 − 2.952 = 1.600 cm. μ = real/apparent = 2.400/1.600 = 1.50. Dividing the real thickness by the shift (0.800 cm) gives 3.00; inverting gives 0.67.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-99","question":"A travelling microscope is focused on a scratch at the bottom of an empty beaker. Water is poured in, and the microscope has to be raised by 1.00 cm to see the scratch clearly again; it then has to be raised by a further 3.00 cm to focus on fine powder floating on the water surface. The refractive index of water from these readings is:","options":["1.33","1.25","0.75","3.00"],"answer":0,"explanation":"The apparent depth is the distance from the image of the scratch up to the surface = 3.00 cm. The real depth is the distance from the scratch itself to the surface = 1.00 + 3.00 = 4.00 cm. μ = 4.00/3.00 = 1.33. Dividing 3.00 by 1.00 (apparent depth by the shift) gives 3.00; 0.75 is the inverse.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-units-measurement-100","question":"In measuring the refractive index of a slab with a travelling microscope (μ = (R₃ − R₁)/(R₃ − R₂)), each of the three readings has an uncertainty of ±0.001 cm. If R₃ − R₁ = 2.400 cm and R₃ − R₂ = 1.600 cm, the maximum percentage error in μ is about:","options":["0.10%","0.21%","0.04%","0.42%"],"answer":1,"explanation":"Each difference of two readings has an uncertainty of ±0.002 cm. Δμ/μ = 0.002/2.400 + 0.002/1.600 = 0.083% + 0.125% ≈ 0.21%. Taking only ±0.001 cm for each difference gives 0.10%. (R₃ appears in both differences, so 0.21% is the conservative maximum normally quoted.)","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-units-measurement-101", "question": "On the forward characteristic of a silicon p-n junction diode, the current is 10 mA at 0.70 V and 20 mA at 0.72 V. The dynamic (a.c.) resistance of the diode in this region is:", "options": ["36 Ω", "70 Ω", "2 Ω", "1 Ω"], "answer": 2, "explanation": "Dynamic resistance r = ΔV/ΔI = (0.72 − 0.70)/(20 − 10) × 10⁻³ = 0.02/0.01 = 2 Ω. The static ratio V/I at 0.72 V (36 Ω) or 0.70 V (70 Ω) is a different quantity.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "phy-units-measurement-102", "question": "How many of the following statements about plotting the characteristics of a p-n junction diode and a Zener diode are correct?\n(A) The Zener characteristic is plotted in reverse bias; beyond breakdown the current rises sharply while the voltage stays nearly constant.\n(B) A microammeter is used for the forward current of an ordinary diode and a milliammeter for its reverse current.\n(C) A Zener diode made with heavier doping has a higher breakdown voltage.\n(D) A series resistor is used in the Zener circuit to limit the current through the diode.", "options": ["Only two", "Only one", "Only three", "All four"], "answer": 0, "explanation": "A and D are correct. B has the meters swapped: the forward current is in mA, while the reverse saturation current is in μA. C is wrong: heavier doping makes a thinner depletion layer and a lower breakdown voltage.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-units-measurement-103", "question": "A 6.0 V Zener diode, in series with a 200 Ω resistor, is connected to a variable d.c. supply, and a 600 Ω load is connected across the Zener. The minimum supply voltage at which the Zener just stays in breakdown and holds the load at 6.0 V is:", "options": ["6.0 V", "7.2 V", "12.0 V", "8.0 V"], "answer": 3, "explanation": "Load current at 6.0 V = 6/600 = 10 mA. At the threshold the Zener current is about zero, so the series current is 10 mA and V_min = 6.0 + 0.010 × 200 = 8.0 V. Below this the load and the 200 Ω simply form a divider, and the Zener stops conducting.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-units-measurement-104","question":"Four components are tested one by one with a multimeter (resistance range), the leads being applied and then reversed. Match each observation (List I) with the component (List II).\nList I: (P) low resistance one way, very high the other way, and it glows in the low-resistance direction; (Q) the same reading in both directions; (R) the reading starts low and rises steadily to a very high value; (S) low resistance one way, very high the other way, with no light.\nList II: (1) resistor; (2) capacitor; (3) LED; (4) p-n junction diode.","options":["P–3, Q–1, R–2, S–4","P–4, Q–1, R–2, S–3","P–3, Q–2, R–1, S–4","P–2, Q–1, R–3, S–4"],"answer":0,"explanation":"Diodes and LEDs conduct only when forward biased; an LED also emits light. A resistor reads the same either way. A capacitor charges through the meter, so the current falls and the reading climbs towards infinity.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "phy-units-measurement-105", "question": "In a mixed collection of components, an item is found that conducts only when its leads are connected one way round and does not emit light. It is most likely:", "options": ["A light-emitting diode", "A p-n junction diode", "A capacitor", "A resistor"], "answer": 1, "explanation": "One-way conduction marks a diode. An LED also conducts one way but glows when forward biased; a resistor conducts equally both ways; a capacitor gives no steady conduction either way.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id":"phy-units-measurement-106","question":"Which of the following is NOT one of the seven SI base units?","options":["kelvin","newton","mole","ampere"],"answer":1,"explanation":"The SI base units are the metre, kilogram, second, ampere, kelvin, mole and candela. The newton is a derived unit (kg m s⁻²).","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-units-measurement-107","question":"The number of significant figures in the measurement 5.00 × 10³ m is:","options":["3","1","4","5"],"answer":0,"explanation":"In scientific notation every digit of the coefficient is significant, including trailing zeros after the decimal point. 5.00 has three significant figures; the power of ten only sets the scale.","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-units-measurement-108","question":"The dimensional formula of magnetic field B (the tesla) is:","options":["[M T⁻¹ A⁻¹]","[M L T⁻² A⁻¹]","[M L² T⁻² A⁻¹]","[M T⁻² A⁻¹]"],"answer":3,"explanation":"From F = qvB, B = F/(qv) = [MLT⁻²]/([AT][LT⁻¹]) = [MT⁻²A⁻¹].","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-units-measurement-109","question":"In the relation P = (a − t²)/(bx), P is pressure, x is a distance and t is time. The dimensions of a/b are:","options":["[M⁻¹ T⁴]","[M L T⁻²]","[M T⁻²]","[T²]"],"answer":2,"explanation":"Only like quantities can be subtracted, so [a] = [T²]. Then [b] = [a]/([P][x]) = T²/(ML⁻¹T⁻² · L) = [M⁻¹T⁴]. Hence [a/b] = T²/(M⁻¹T⁴) = [MT⁻²].","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-units-measurement-110","question":"The frequency f of small oscillations of a liquid drop is assumed to depend only on its surface tension S, its density ρ and its radius r. Dimensional analysis gives f proportional to:","options":["√(S/(ρr))","√(Sρ/r³)","√(S/(ρr³))","S/(ρr²)"],"answer":2,"explanation":"Let f ∝ S^a ρ^b r^c with [S] = MT⁻², [ρ] = ML⁻³. Mass: a + b = 0; time: −2a = −1, so a = ½ and b = −½; length: −3b + c = 0, so c = −3/2. Thus f ∝ √(S/(ρr³)).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-units-measurement-111","question":"Which combination of Planck's constant h, the speed of light c and the gravitational constant G has the dimensions of MASS?","options":["√(hG/c³)","√(hc/G)","√(hG/c⁵)","hc/G"],"answer":1,"explanation":"[h] = ML²T⁻¹, [c] = LT⁻¹, [G] = M⁻¹L³T⁻². hc/G = (ML²T⁻¹)(LT⁻¹)/(M⁻¹L³T⁻²) = M², so √(hc/G) is a mass (the Planck mass). √(hG/c³) is a length and √(hG/c⁵) a time.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-units-measurement-112","question":"In a simple-pendulum experiment the effective length is measured as 100.0 cm with an uncertainty of 0.1 cm, and the time for 20 oscillations as 40.0 s with an uncertainty of 0.1 s. The maximum percentage error in the value of g obtained is:","options":["0.6%","0.35%","0.25%","0.5%"],"answer":0,"explanation":"g = 4π²L/T², so Δg/g = ΔL/L + 2ΔT/T. ΔL/L = 0.1%; ΔT/T = 0.1/40 = 0.25% (the same fraction for one period), doubled to 0.5%. Total = 0.6%.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-units-measurement-113","question":"The density of a cube is found by measuring its mass and the length of an edge. The maximum errors are 1% in the mass and 2% in the length. The maximum error in the density is:","options":["9%","3%","5%","7%"],"answer":3,"explanation":"ρ = m/L³, so Δρ/ρ = Δm/m + 3ΔL/L = 1% + 6% = 7%.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-units-measurement-114","question":"Two resistors, (6.0 ± 0.3) Ω and (3.0 ± 0.1) Ω, are connected in parallel. Their equivalent resistance with its maximum error is about:","options":["(2.0 ± 0.04) Ω","(2.0 ± 0.4) Ω","(2.0 ± 0.13) Ω","(2.0 ± 0.08) Ω"],"answer":3,"explanation":"1/R = 1/R₁ + 1/R₂ gives ΔR/R² = ΔR₁/R₁² + ΔR₂/R₂². So ΔR = 4 × (0.3/36 + 0.1/9) = 4 × (0.0083 + 0.0111) ≈ 0.078 Ω. Simply adding the errors (0.4 Ω) or relative errors overestimates it.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-units-measurement-115","question":"In an unusual vernier callipers, 10 divisions of the vernier scale coincide with 11 divisions of the main scale, each main-scale division being 1 mm. The least count of this instrument is:","options":["1.1 mm","0.09 mm","0.1 mm","0.11 mm"],"answer":2,"explanation":"One vernier division = 11/10 = 1.1 mm. The least count is the magnitude of the difference between one vernier division and one main-scale division: |1.1 − 1.0| = 0.1 mm (this 'retrograde' vernier is read in the opposite sense).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-units-measurement-116","question":"A spherometer with its three legs at the corners of an equilateral triangle of side 3 cm is used on a curved surface, and the central screw has to be raised by 0.5 cm above the plane of the legs to touch the surface. The radius of curvature of the surface is:","options":["3 cm","3.25 cm","6.25 cm","9.25 cm"],"answer":1,"explanation":"For a spherometer, R = l²/6h + h/2, where l is the distance between the legs. R = 9/3 + 0.25 = 3.25 cm.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-units-measurement-117","question":"At high speeds the drag force on a sphere moving through a fluid depends only on the fluid density ρ, the speed v and the radius r. If the speed is doubled and the radius halved, the drag force:","options":["remains the same","doubles","is halved","becomes four times as large"],"answer":0,"explanation":"Dimensional analysis: F ∝ ρ^a v^b r^c with [F] = MLT⁻² gives a = 1, b = 2, c = 2, so F ∝ ρv²r². Doubling v (×4) and halving r (×1/4) leaves F unchanged.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-units-measurement-118","question":"In a system of units the unit of mass is 1 g, the unit of length is 1 cm and the unit of time is 1 ms. One joule expressed in this system is:","options":["10 units","10⁷ units","10⁻¹ units","10⁴ units"],"answer":0,"explanation":"1 J = 1 kg m² s⁻² = (10³ g)(10² cm)²(10³ ms)⁻² = 10³ × 10⁴ × 10⁻⁶ = 10 units.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-units-measurement-119","question":"The displacement of a particle is given by y = A sin(ωt − kx) + Bt, where t is time and x is a distance. The dimensions of B are:","options":["[L T⁻²]","[L]","[T⁻¹]","[L T⁻¹]"],"answer":3,"explanation":"Each term must have the dimensions of y, a length. So [Bt] = L and [B] = [LT⁻¹], a velocity. (ωt and kx are dimensionless phases.)","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-units-measurement-120","question":"Two lengths, 2.5 × 10³ m and 3.42 × 10² m, are added. The sum, written to the correct number of significant figures, is:","options":["2.84 × 10³ m","2.842 × 10³ m","2.8 × 10³ m","2.9 × 10³ m"],"answer":2,"explanation":"In addition, the result keeps as many decimal places as the least precise term. 2.5 × 10³ m is known only to the nearest 100 m, so 2842 m rounds to 2.8 × 10³ m.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-units-measurement-121","question":"The Stefan–Boltzmann constant σ (in P = σAT⁴) has the dimensional formula:","options":["[M L² T⁻³ K⁻⁴]","[M T⁻³ K⁻⁴]","[M L T⁻³ K⁻⁴]","[M T⁻² K⁻⁴]"],"answer":1,"explanation":"σ = P/(AT⁴) = [ML²T⁻³]/([L²][K⁴]) = [MT⁻³K⁻⁴].","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-units-measurement-122","question":"The constant b in Wien's displacement law (λ_max T = b) has the dimensions of:","options":["[L K⁻¹]","[L K]","[L⁻¹ K]","[M L² T⁻² K⁻¹]"],"answer":1,"explanation":"b = λ_max × T, a length times a temperature: [LK] (its SI value is about 2.9 × 10⁻³ m K).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-units-measurement-123","question":"In a potentiometer experiment, a cell gives a balance length of 280 cm on open circuit. When a 12 Ω resistor is connected across the cell, the balance length becomes 240 cm. The internal resistance of the cell is:","options":["2 Ω","1.71 Ω","14 Ω","0.5 Ω"],"answer":0,"explanation":"The balance length measures E on open circuit and the terminal voltage V with the shunt. r = R(E/V − 1) = R(l₁/l₂ − 1) = 12 × (280/240 − 1) = 12 × 1/6 = 2 Ω.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-units-measurement-124","question":"A potentiometer wire 10 m long has a resistance of 10 Ω. It is connected in series with a 10 Ω rheostat across a 4 V cell of negligible internal resistance. A cell of emf 1.5 V is balanced on the wire at a length of:","options":["1.5 m","3.75 m","5 m","7.5 m"],"answer":3,"explanation":"Current = 4/20 = 0.2 A, so the drop across the wire is 2 V and the potential gradient is 0.2 V/m. Balance length = 1.5/0.2 = 7.5 m.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-units-measurement-125","question":"To measure the period of a pendulum, a student times 50 oscillations instead of one with the same stopwatch. The main benefit is that:","options":["systematic errors in the stopwatch are removed","the pendulum's amplitude stays constant","the reaction-time and reading errors are spread over 50 periods, so the error in one period becomes 50 times smaller","air resistance no longer affects the period"],"answer":2,"explanation":"The uncertainty in starting and stopping the watch (say 0.2 s) is roughly fixed, whatever interval is timed. Dividing a long interval by 50 reduces the uncertainty per period by that factor. It does not remove a stopwatch's systematic error.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-units-measurement-126","question":"The velocity of a particle is given by v = at + b/(t + c), where t is time. The dimensions of b and c are respectively:","options":["[L T⁻²] and [T⁻¹]","[L T⁻¹] and [T]","[L] and [T]","[L] and [T⁻¹]"],"answer":2,"explanation":"c is added to t, so [c] = [T]. Then b/(t + c) must be a velocity: [b] = [LT⁻¹][T] = [L]. (And [a] = [LT⁻²].)","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-units-measurement-127","question":"The radius of a circle is measured as 2.50 cm. Its area, written to the correct number of significant figures (π taken as exact), is:","options":["19.63 cm²","19.6 cm²","20 cm²","19.635 cm²"],"answer":1,"explanation":"A = πr² = π × 6.25 = 19.634… cm². The radius has three significant figures, so the area is quoted to three: 19.6 cm².","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-units-measurement-128","question":"A student finds g by timing a ball dropped from rest through a height of (1.00 ± 0.01) m, measuring the fall time as (0.45 ± 0.01) s. The maximum percentage error in g is about:","options":["5.4%","3.2%","1%","2.2%"],"answer":0,"explanation":"h = ½gt², so g = 2h/t² and Δg/g = Δh/h + 2Δt/t = 1% + 2 × 2.2% ≈ 5.4%. The short time interval makes timing the dominant source of error.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-units-measurement-129","question":"Here k is the Boltzmann constant, T a temperature, h Planck's constant and c the speed of light. The quantity kT/(hc) has the dimensions of:","options":["it is dimensionless","frequency","energy","inverse length"],"answer":3,"explanation":"kT is an energy, and hc is energy × length (since E = hc/λ). So kT/(hc) has dimensions [L⁻¹], i.e. a wave number.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-units-measurement-130","question":"The volume of liquid flowing per second, Q, through a narrow tube is assumed to depend on the pressure gradient (Δp/l), the viscosity η and the tube's radius r. Dimensional analysis gives:","options":["Q ∝ (Δp/l) r²/η","Q ∝ (Δp/l) r³/η","Q ∝ (Δp/l) η r⁴","Q ∝ (Δp/l) r⁴/η"],"answer":3,"explanation":"With [Q] = L³T⁻¹, [Δp/l] = ML⁻²T⁻², [η] = ML⁻¹T⁻¹: let Q ∝ (Δp/l)^a η^b r^c. Mass: a + b = 0; time: −2a − b = −1, so a = 1, b = −1; length: −2a − b + c = 3, so c = 4. This reproduces Poiseuille's r⁴ law.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-units-measurement-131","question":"A length is found as the difference X = a − b of two readings a = (50 ± 0.5) cm and b = (48 ± 0.5) cm. The percentage error in X is:","options":["1%","2%","50%","25%"],"answer":2,"explanation":"Absolute errors add in a difference: X = (2 ± 1) cm, so the relative error is 1/2 = 50%. Subtracting nearly equal quantities magnifies the relative error enormously.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-units-measurement-132","question":"The period T of a satellite skimming the surface of a planet is assumed to depend only on the planet's mean density ρ, its radius R and the gravitational constant G. Dimensional analysis shows that T is proportional to:","options":["R(Gρ)^(−1/2)","(Gρ)^(−1/2), independent of R","R^(3/2)(Gρ)^(−1/2)","(GρR²)^(−1/2)"],"answer":1,"explanation":"Let T ∝ G^a ρ^b R^c with [G] = M⁻¹L³T⁻² and [ρ] = ML⁻³. Time: −2a = 1, so a = −½; mass: −a + b = 0, so b = −½; length: 3a − 3b + c = 0, so c = 0. Hence T ∝ 1/√(Gρ), with no dependence on R.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-units-measurement-133","question":"Three readings of a length, made with an instrument whose zero error has gone unnoticed, are 2.30 cm, 2.31 cm and 2.30 cm; the true length is 2.50 cm. These measurements are best described as:","options":["precise but not accurate","accurate but not precise","both precise and accurate","neither precise nor accurate, because they are random"],"answer":0,"explanation":"Precision is about the spread of repeated readings (very small here), while accuracy is closeness to the true value (off by 0.2 cm). An unnoticed zero error is a systematic error, which spoils accuracy without affecting precision.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-units-measurement-134","question":"The dimensional formula of self-inductance (the henry) is:","options":["[M L² T⁻² A⁻²]","[M L² T⁻¹ A⁻²]","[M L² T⁻² A⁻¹]","[M L T⁻² A⁻²]"],"answer":0,"explanation":"Energy stored U = ½LI², so L = 2U/I² = [ML²T⁻²]/[A²] = [ML²T⁻²A⁻²].","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-units-measurement-135","question":"Following the rules for significant figures, the value of 1.0 ÷ 3.00 should be written as:","options":["0.3333","0.333","0.3","0.33"],"answer":3,"explanation":"In division the result keeps as many significant figures as the factor with the fewest: 1.0 has two. So 0.3333… is written as 0.33.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-units-measurement-136","question":"An angle is measured as θ = 30° ± 1°. The percentage error in the value of sin θ is about:","options":["1.7%","3.3%","3.0%","1.0%"],"answer":2,"explanation":"Δ(sin θ) = cos θ Δθ with Δθ in radians: 0.866 × (π/180) ≈ 0.0151. Relative error = 0.0151/0.5 ≈ 3.0%. (3.3% would be the error in θ itself, 1°/30°.)","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-units-measurement-137","question":"A student's pendulum experiment consistently gives g slightly LARGER than the accepted value, while the stopwatch is accurate. Which mistake would produce this?","options":["Measuring the length only up to the top of the bob","Measuring the length from the point of suspension to the bottom of the bob instead of to its centre","Counting one oscillation fewer than were actually timed","Using a heavier bob of the same size"],"answer":1,"explanation":"g = 4π²L/T². Taking L to the bottom of the bob overestimates L (by the bob's radius) and so overestimates g. Measuring only to the top of the bob underestimates L. The bob's mass does not affect the period.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-units-measurement-138","question":"Which of the following equations is dimensionally INCORRECT (u, v velocities, a acceleration, s displacement, t time)?","options":["s = ut + ½at²","v² = u² + 2as²","v = u + at","s = (u + v)t/2"],"answer":1,"explanation":"In v² = u² + 2as², the last term has dimensions (LT⁻²)(L²) = L³T⁻², not L²T⁻². All the others are dimensionally consistent (dimensional consistency does not prove correctness, but inconsistency proves an error).","difficulty":"moderate","source":"JEE Main"},
];

export default questions;
